/**
 * Orchestrator side-effect: apply the auto-ready rule.
 *
 * When a task is marked done, scan sibling tasks in the same feature and
 * transition any whose entire `depends_on` list is now satisfied from
 * `todo` → `ready`. Called by `handleMergedPrs` after writing task.status = "done".
 *
 * This module extracts the auto-ready logic from `poll/handle-merged-prs.ts`
 * into a standalone side-effect so it can be tested and invoked independently.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { readdirSync } from "node:fs";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task } from "../types/task.js";
import { featuresRoot, taskYamlRelPath, TASKS_DIR } from "../paths.js";

export interface UnblockDepsOpts {
  workspaceRoot: string;
  featureId: string;
  /** The task ID that was just marked done — used as the anchor for dep checks. */
  completedTaskId: string;
  gitAuthorEmail: string;
}

export interface UnblockDepsResult {
  /** Relative paths of all YAML files mutated (for git add). */
  mutatedRelPaths: string[];
  /** IDs of tasks that were transitioned to ready. */
  readiedTaskIds: string[];
}

/**
 * Scan sibling task YAMLs in the same feature directory. For each that is in
 * `todo` status and whose entire `depends_on` list is satisfied (all done),
 * write `status: ready` and append a ready log entry.
 *
 * Writes directly to disk — the caller is responsible for git add/commit.
 *
 * Non-throwing: individual sibling read/write errors are skipped silently to
 * avoid blocking the overall done-transition on one bad sibling file.
 */
export function applyAutoReadyRule(opts: UnblockDepsOpts): UnblockDepsResult {
  const { workspaceRoot, featureId, completedTaskId, gitAuthorEmail } = opts;

  const tasksDir = join(featuresRoot(workspaceRoot), featureId, TASKS_DIR);
  const mutatedRelPaths: string[] = [];
  const readiedTaskIds: string[] = [];

  let siblingFiles: string[] = [];
  try {
    siblingFiles = readdirSync(tasksDir).filter(
      (f) => /^T\d+\.yaml$/.test(f) && f !== `${completedTaskId}.yaml`,
    );
  } catch {
    return { mutatedRelPaths, readiedTaskIds };
  }

  // Build a status map including the just-completed task.
  const taskStatusMap = new Map<string, string>([[completedTaskId, "done"]]);
  for (const sibFile of siblingFiles) {
    try {
      const sibTask = parseYaml(
        readFileSync(join(tasksDir, sibFile), "utf-8"),
      ) as Task;
      taskStatusMap.set(sibTask.id, sibTask.status);
    } catch { /* skip */ }
  }

  for (const sibFile of siblingFiles) {
    try {
      const sibPath = join(tasksDir, sibFile);
      const sibTask = parseYaml(readFileSync(sibPath, "utf-8")) as Task;

      if (sibTask.status !== "todo") continue;
      if (!Array.isArray(sibTask.depends_on) || !sibTask.depends_on.includes(completedTaskId)) continue;

      const allDepsDone = sibTask.depends_on.every(
        (depId) => taskStatusMap.get(depId) === "done",
      );
      if (!allDepsDone) continue;

      const now = new Date().toISOString();
      sibTask.status = "ready";
      sibTask.log.push({
        action: "ready",
        by: gitAuthorEmail,
        at: now,
        note: `Task activated — dependency ${completedTaskId} merged and marked done.`,
      });

      writeFileSync(sibPath, yamlStringify(sibTask), "utf-8");
      mutatedRelPaths.push(taskYamlRelPath(featureId, sibTask.id));
      readiedTaskIds.push(sibTask.id);
    } catch { /* skip individual sibling errors */ }
  }

  return { mutatedRelPaths, readiedTaskIds };
}

