import { readFileSync, writeFileSync } from "node:fs";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task } from "../types/task.js";
import { taskYamlAbsPath } from "../paths.js";

export function readTask(workspaceRoot: string, featureId: string, taskId: string): Task {
  return parseYaml(
    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
  ) as Task;
}

export function writeTask(workspaceRoot: string, featureId: string, task: Task): void {
  writeFileSync(
    taskYamlAbsPath(workspaceRoot, featureId, task.id),
    yamlStringify(task),
    "utf-8",
  );
}

