/**
 * Orchestrator side-effect: write terminal task status to the task YAML.
 *
 * Called after the executor returns a result. Translates ExecutorResult
 * terminal_status values into the workflow task status schema and commits
 * the change to the management repo's task branch.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { execSync, spawnSync } from "node:child_process";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task } from "../types/task.js";
import type { ExecutorResult } from "@workflow/runtime-abi";
import { taskYamlAbsPath, taskYamlRelPath } from "../paths.js";
import { buildGitEnv } from "../git-env.js";

export interface MutateTaskYamlOpts {
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  result: ExecutorResult;
  /**
   * Implementation repo PR URL — reported by the executor in result.json.pr_url.
   * Recorded whenever present, regardless of terminal_status. A blocked task
   * with a draft PR still records its pr_url.
   */
  prUrl?: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
}

/**
 * Write the terminal task status implied by ExecutorResult to the task YAML
 * and commit+push to the task branch.
 *
 * Status transitions:
 *   in_review → task.status = "in_review", task.pr.url = prUrl (when present)
 *   blocked   → task.status = "blocked", task.blocked_reason + task.blocked_suggestion
 *               task.pr.url = prUrl when present (draft PR documents failed attempt)
 *   failed    → task.status = "blocked", task.blocked_reason = "executor_failed:<reason>"
 *               task.pr.url = prUrl when present
 *
 * Non-throwing: returns an error string on failure so the caller can decide
 * whether to surface or swallow the error.
 */
export function mutateTaskYaml(opts: MutateTaskYamlOpts): string | undefined {
  const {
    workspaceRoot,
    featureId,
    taskId,
    taskBranch,
    result,
    prUrl,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
  } = opts;

  const now = new Date().toISOString();
  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const relPath = taskYamlRelPath(featureId, taskId);
  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
  const statusLabel = result.terminal_status === "in_review" ? "in_review" : "blocked";

  // Step 1: Move to the task branch tip BEFORE touching any files.
  // Discard local changes first — a previous failed cycle may have written the
  // YAML and then crashed before committing, leaving a dirty working tree that
  // would block the checkout.
  try {
    execSync(`git -C "${workspaceRoot}" fetch origin "${taskBranch}"`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" checkout -- .`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" checkout -B "${taskBranch}" "origin/${taskBranch}"`,
      { env, stdio: "pipe" },
    );
  } catch (e) {
    return `git fetch/checkout task branch failed: ${String(e)}`;
  }

  // Step 2: Read the task YAML from the branch tip.
  let task: Task;
  try {
    task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
  } catch (e) {
    return `failed to read task YAML: ${String(e)}`;
  }

  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;

  switch (result.terminal_status) {
    case "in_review":
      task.status = "in_review";
      break;

    case "blocked":
      task.status = "blocked";
      task.blocked_reason = result.blocked_reason ?? "unknown";
      if (result.blocked_suggestion) {
        task.blocked_suggestion = result.blocked_suggestion;
      }
      break;

    case "failed":
      task.status = "blocked";
      task.blocked_reason = `executor_failed:${result.blocked_reason ?? "unknown"}`;
      if (result.blocked_suggestion) {
        task.blocked_suggestion = result.blocked_suggestion;
      }
      break;
  }

  // Record pr_url on any terminal_status — executor reports it whenever a PR was opened.
  // A blocked task with a draft PR still records pr.url so the failed attempt is documented.
  if (prUrl) {
    task.pr = { url: prUrl, status: "open" };
  }

  // Step 3: Write the modified YAML.
  try {
    writeFileSync(yamlPath, yamlStringify(task), "utf-8");
  } catch (e) {
    return `failed to write task YAML: ${String(e)}`;
  }

  try {
    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" commit -m "chore(${taskId}): status → ${statusLabel}"`,
      { env, stdio: "pipe" },
    );
  } catch (e) {
    return `git add/commit failed: ${String(e)}`;
  }

  const push = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
    env,
    encoding: "utf-8",
  });
  if (push.status !== 0) {
    return `git push failed: ${push.stderr}`;
  }

  return undefined;
}

