/**
 * Shared git environment helper.
 *
 * Pass `identity` when the git operation produces a commit (add/commit/push).
 * Omit it for read-only operations (clone/fetch/pull).
 */
export function buildGitEnv(
  sshKeyPath: string | undefined,
  identity?: { email: string; name: string },
): NodeJS.ProcessEnv {
  return {
    ...process.env,
    ...(identity && {
      GIT_AUTHOR_NAME: identity.name,
      GIT_AUTHOR_EMAIL: identity.email,
      GIT_COMMITTER_NAME: identity.name,
      GIT_COMMITTER_EMAIL: identity.email,
    }),
    ...(sshKeyPath && {
      GIT_SSH_COMMAND: `ssh -i ${sshKeyPath} -o StrictHostKeyChecking=no`,
    }),
  } as NodeJS.ProcessEnv;
}

