/**
 * Unit tests for side-effects/unblock-deps.ts (applyAutoReadyRule).
 *
 * No git operations — applyAutoReadyRule only reads/writes files.
 * Uses real temp directories.
 *
 * Covers:
 *   1. No sibling depends on completedTaskId → empty result
 *   2. Single sibling with satisfied dep → readied
 *   3. Multiple siblings with satisfied deps → all readied
 *   4. Sibling with partial dep satisfaction → NOT readied
 *   5. Non-todo sibling (in_progress, done) → NOT readied
 *   6. Missing tasks directory → returns empty (no throw)
 *   7. Readied task gets "ready" log entry with completedTaskId mentioned
 */

import { describe, it, expect, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { stringify as yamlStringify, parse as parseYaml } from "yaml";
import type { Task } from "../src/types/task.js";
import { applyAutoReadyRule } from "../src/side-effects/unblock-deps.js";

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "test-feature";
const GIT_AUTHOR_EMAIL = "agent@test.com";

function makeTask(id: string, overrides: Partial<Task> = {}): Task {
  return {
    id,
    title: `Task ${id}`,
    repo: "test-repo",
    status: "todo",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: `feature/${FEATURE_ID}-${id}`,
    execution: {
      actor_type: "agent",
      last_updated_by: null,
      last_updated_at: null,
    },
    pr: { url: "", status: "not_created" },
    workspace_pr: null,
    log: [],
    ...overrides,
  };
}

// ── Temp directory helpers ────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspaceWithTasks(tasks: Task[]): string {
  const dir = mkdtempSync(join(tmpdir(), "unblock-deps-unit-"));
  tmpDirs.push(dir);
  const tasksDir = join(dir, "docs", "features", FEATURE_ID, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  for (const task of tasks) {
    writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");
  }
  return dir;
}

function readTaskFromDir(wsRoot: string, taskId: string): Task {
  return parseYaml(
    readFileSync(
      join(wsRoot, "docs", "features", FEATURE_ID, "tasks", `${taskId}.yaml`),
      "utf-8",
    ),
  ) as Task;
}

afterEach(() => {
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
});

const baseOpts = {
  featureId: FEATURE_ID,
  gitAuthorEmail: GIT_AUTHOR_EMAIL,
};

// ── 1. No sibling depends on completedTaskId ──────────────────────────────────

describe("applyAutoReadyRule — no applicable siblings", () => {
  it("returns empty when no sibling depends on completedTaskId", () => {
    const t1 = makeTask("T1", { status: "done" });
    const t2 = makeTask("T2", { depends_on: ["T3"] }); // depends on T3, not T1
    const wsRoot = makeWorkspaceWithTasks([t1, t2]);

    const result = applyAutoReadyRule({ ...baseOpts, workspaceRoot: wsRoot, completedTaskId: "T1" });

    expect(result.readiedTaskIds).toHaveLength(0);
    expect(result.mutatedRelPaths).toHaveLength(0);
    expect(readTaskFromDir(wsRoot, "T2").status).toBe("todo");
  });

  it("returns empty when the tasks directory has no siblings", () => {
    const wsRoot = makeWorkspaceWithTasks([makeTask("T1", { status: "done" })]);

    const result = applyAutoReadyRule({ ...baseOpts, workspaceRoot: wsRoot, completedTaskId: "T1" });

    expect(result.readiedTaskIds).toHaveLength(0);
  });
});

// ── 2. Single sibling with satisfied dep → readied ───────────────────────────

describe("applyAutoReadyRule — single sibling", () => {
  it("transitions sibling from todo to ready when its only dep is now done", () => {
    const t1 = makeTask("T1", { status: "done" });
    const t2 = makeTask("T2", { depends_on: ["T1"] });
    const wsRoot = makeWorkspaceWithTasks([t1, t2]);

    const result = applyAutoReadyRule({ ...baseOpts, workspaceRoot: wsRoot, completedTaskId: "T1" });

    expect(result.readiedTaskIds).toEqual(["T2"]);
    expect(result.mutatedRelPaths.length).toBe(1);

    const t2Updated = readTaskFromDir(wsRoot, "T2");
    expect(t2Updated.status).toBe("ready");
  });

  it("appends a ready log entry mentioning completedTaskId", () => {
    const t1 = makeTask("T1", { status: "done" });
    const t2 = makeTask("T2", { depends_on: ["T1"] });
    const wsRoot = makeWorkspaceWithTasks([t1, t2]);

    applyAutoReadyRule({ ...baseOpts, workspaceRoot: wsRoot, completedTaskId: "T1" });

    const t2Updated = readTaskFromDir(wsRoot, "T2");
    const readyEntry = t2Updated.log.find((e) => e.action === "ready");
    expect(readyEntry).toBeDefined();
    expect(readyEntry?.note).toContain("T1");
    expect(readyEntry?.by).toBe(GIT_AUTHOR_EMAIL);
  });
});

// ── 3. Multiple siblings with satisfied deps → all readied ───────────────────

describe("applyAutoReadyRule — multiple siblings", () => {
  it("readies all siblings whose only dep is the completed task", () => {
    const t1 = makeTask("T1", { status: "done" });
    const t2 = makeTask("T2", { depends_on: ["T1"] });
    const t3 = makeTask("T3", { depends_on: ["T1"] });
    const wsRoot = makeWorkspaceWithTasks([t1, t2, t3]);

    const result = applyAutoReadyRule({ ...baseOpts, workspaceRoot: wsRoot, completedTaskId: "T1" });

    expect(result.readiedTaskIds.sort()).toEqual(["T2", "T3"]);
    expect(readTaskFromDir(wsRoot, "T2").status).toBe("ready");
    expect(readTaskFromDir(wsRoot, "T3").status).toBe("ready");
  });
});

// ── 4. Partial dep satisfaction → NOT readied ─────────────────────────────────

describe("applyAutoReadyRule — partial dep satisfaction", () => {
  it("does not ready a sibling when one of its deps is still pending", () => {
    const t1 = makeTask("T1", { status: "done" });
    const t2 = makeTask("T2", { status: "todo" }); // not yet done
    // T3 depends on both T1 and T2; T2 is not done
    const t3 = makeTask("T3", { depends_on: ["T1", "T2"] });
    const wsRoot = makeWorkspaceWithTasks([t1, t2, t3]);

    const result = applyAutoReadyRule({ ...baseOpts, workspaceRoot: wsRoot, completedTaskId: "T1" });

    expect(result.readiedTaskIds).toHaveLength(0);
    expect(readTaskFromDir(wsRoot, "T3").status).toBe("todo");
  });

  it("readies a sibling when ALL its deps are now done", () => {
    const t1 = makeTask("T1", { status: "done" });
    // T2 is already done (pre-existing)
    const t2 = makeTask("T2", { status: "done" });
    // T3 depends on T1 and T2 — both done after T1 completes
    const t3 = makeTask("T3", { depends_on: ["T1", "T2"] });
    const wsRoot = makeWorkspaceWithTasks([t1, t2, t3]);

    const result = applyAutoReadyRule({ ...baseOpts, workspaceRoot: wsRoot, completedTaskId: "T1" });

    expect(result.readiedTaskIds).toEqual(["T3"]);
    expect(readTaskFromDir(wsRoot, "T3").status).toBe("ready");
  });
});

// ── 5. Non-todo siblings are not modified ─────────────────────────────────────

describe("applyAutoReadyRule — non-todo siblings", () => {
  it("does not modify a sibling that is already in_progress", () => {
    const t1 = makeTask("T1", { status: "done" });
    const t2 = makeTask("T2", { status: "in_progress", depends_on: ["T1"] });
    const wsRoot = makeWorkspaceWithTasks([t1, t2]);

    applyAutoReadyRule({ ...baseOpts, workspaceRoot: wsRoot, completedTaskId: "T1" });

    expect(readTaskFromDir(wsRoot, "T2").status).toBe("in_progress");
  });

  it("does not modify a sibling that is already done", () => {
    const t1 = makeTask("T1", { status: "done" });
    const t2 = makeTask("T2", { status: "done", depends_on: ["T1"] });
    const wsRoot = makeWorkspaceWithTasks([t1, t2]);

    applyAutoReadyRule({ ...baseOpts, workspaceRoot: wsRoot, completedTaskId: "T1" });

    const t2Updated = readTaskFromDir(wsRoot, "T2");
    expect(t2Updated.status).toBe("done");
    expect(t2Updated.log.filter((e) => e.action === "ready")).toHaveLength(0);
  });
});

// ── 6. Missing tasks directory → returns empty ───────────────────────────────

describe("applyAutoReadyRule — missing tasks directory", () => {
  it("returns empty without throwing when tasks directory does not exist", () => {
    const dir = mkdtempSync(join(tmpdir(), "unblock-no-tasks-"));
    tmpDirs.push(dir);

    const result = applyAutoReadyRule({ ...baseOpts, workspaceRoot: dir, completedTaskId: "T1" });

    expect(result.readiedTaskIds).toHaveLength(0);
    expect(result.mutatedRelPaths).toHaveLength(0);
  });
});

