/**
 * Unit tests for side-effects/mutate-task-yaml.ts (mutateTaskYaml).
 *
 * Git operations (execSync, spawnSync) are mocked via vi.mock.
 * File I/O uses real temp directories.
 *
 * Covers:
 *   1. terminal_status: "in_review" → task.status = "in_review", pr set
 *   2. terminal_status: "in_review" without prUrl → pr not set (no crash)
 *   3. terminal_status: "blocked" → task.status = "blocked", blocked_reason + suggestion
 *   4. terminal_status: "blocked" without suggestion → task.blocked_suggestion not set
 *   5. terminal_status: "failed" → task.status = "blocked", blocked_reason = "executor_failed:..."
 *   6. Missing YAML file → returns error string (non-throwing)
 *   7. execution.last_updated_by is set on every call
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execSync, spawnSync } from "node:child_process";
import { stringify as yamlStringify, parse as parseYaml } from "yaml";
import type { Task } from "../src/types/task.js";
import { mutateTaskYaml } from "../src/side-effects/mutate-task-yaml.js";

// ── Mock git operations ───────────────────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "test-feature";
const TASK_ID = "T2";
const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
const GIT_AUTHOR_EMAIL = "agent@test.com";
const GIT_AUTHOR_NAME = "Test Agent";

function makeTask(overrides: Partial<Task> = {}): Task {
  return {
    id: TASK_ID,
    title: "Test Task",
    repo: "test-repo",
    status: "in_progress",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: TASK_BRANCH,
    execution: {
      actor_type: "agent",
      last_updated_by: null,
      last_updated_at: null,
    },
    pr: { url: "", status: "not_created" },
    workspace_pr: null,
    log: [],
    ...overrides,
  };
}

// ── Temp directory helpers ────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspaceWithTask(task: Task): string {
  const dir = mkdtempSync(join(tmpdir(), "mutate-yaml-unit-"));
  tmpDirs.push(dir);
  const tasksDir = join(dir, "docs", "features", FEATURE_ID, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");
  return dir;
}

