/**
 * Orchestrator side-effect: append a log entry to a task YAML file.
 *
 * Handles the git add/commit/push of the updated YAML to the task's feature
 * branch. All callers delegate log-entry appending here rather than writing
 * directly to avoid duplicating the git plumbing.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { execSync, spawnSync } from "node:child_process";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task, TaskLogEntry } from "../types/task.js";
import { taskYamlAbsPath, taskYamlRelPath } from "../paths.js";
import { buildGitEnv } from "../git-env.js";

export interface AppendLogOpts {
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  entry: Omit<TaskLogEntry, "at"> & { at?: string };
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  commitMessage?: string;
}

/**
 * Append a log entry to the task YAML on disk and commit+push to the task branch.
 *
 * Non-throwing: errors are returned as strings rather than thrown so the caller
 * can decide how to handle a partial log failure without halting the cycle.
 *
 * Returns undefined on success, or an error string on failure.
 */
export function appendLogEntry(opts: AppendLogOpts): string | undefined {
  const {
    workspaceRoot,
    featureId,
    taskId,
    taskBranch,
    entry,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    commitMessage,
  } = opts;

  const at = entry.at ?? new Date().toISOString();
  const fullEntry: TaskLogEntry = { ...entry, at } as TaskLogEntry;

  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const relPath = taskYamlRelPath(featureId, taskId);
  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
  const msg = commitMessage ?? `chore(${taskId}): append ${fullEntry.action} log entry`;

  // Step 1: Re-anchor to the task branch tip BEFORE reading or writing any files.
  // checkout -B resets the working tree to origin state, so any prior local
  // writes must happen after this step — not before.
  try {
    execSync(`git -C "${workspaceRoot}" fetch origin "${taskBranch}"`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" checkout -- .`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" checkout -B "${taskBranch}" "origin/${taskBranch}"`,
      { env, stdio: "pipe" },
    );
  } catch (e) {
    return `git fetch/checkout task branch failed: ${String(e)}`;
  }

  // Step 2: Read YAML from the now-correct branch state.
  let task: Task;
  try {
    task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
  } catch (e) {
    return `failed to read task YAML: ${String(e)}`;
  }

  task.log.push(fullEntry);
  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = at;

  // Step 3: Write the mutated YAML (after checkout so the write is not overwritten).
  try {
    writeFileSync(yamlPath, yamlStringify(task), "utf-8");
  } catch (e) {
    return `failed to write task YAML: ${String(e)}`;
  }

  try {
    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" commit -m "${msg}"`, { env, stdio: "pipe" });
  } catch (e) {
    return `git add/commit failed: ${String(e)}`;
  }

  const push = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
    env,
    encoding: "utf-8",
  });
  if (push.status !== 0) {
    return `git push failed: ${push.stderr}`;
  }

  return undefined;
}

