/**
 * Tests for T2 dispatch controller logic:
 *   1. dispatchReviewResult routing (passed, escalate, unknown, change_requested)
 *   2. findFixableTasks eligibility
 *   3. findReviewableTasks eligibility
 *   4. dispatchExecutorResult max-turns retry
 */

import { describe, it, expect, vi, afterEach } from "vitest";
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { stringify as yamlStringify } from "yaml";
import { spawnSync } from "node:child_process";
import type { Task } from "../src/types/task.js";

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "ctrl-feature";
const TASK_ID = "T1";
const MGMT_GITHUB = "https://github.com/testorg/mgmt-repo";

function makeTask(overrides: Partial<Task> = {}): Task {
  return {
    id: TASK_ID,
    title: "Test Task",
    repo: "my-repo",
    status: "in_review",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: `feature/${FEATURE_ID}-${TASK_ID}`,
    execution: { actor_type: "agent", last_updated_by: null, last_updated_at: null },
    pr: { url: "https://github.com/org/repo/pull/1", status: "open" },
    workspace_pr: null,
    log: [],
    ...overrides,
  };
}

function mockGitShow(task: Task): ReturnType<typeof spawnSync> {
  return {
    pid: 0, output: [], stdout: yamlStringify(task),
    stderr: "", status: 0, signal: null, error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

function mockPushSuccess(): ReturnType<typeof spawnSync> {
  return {
    pid: 0, output: [], stdout: "", stderr: "",
    status: 0, signal: null, error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

// ── Temp workspace helpers ────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspace(tasks: Task[], featureId = FEATURE_ID, mgmtGithub = MGMT_GITHUB): string {
  const wsDir = mkdtempSync(join(tmpdir(), "dispatch-ctrl-"));
