/**
 * Unit tests for the Auto-Done Writer (T5):
 *   dispatchReviewResult "passed" branch + writeDoneAndCascade.
 *
 * Tests:
 *   1. passed — single task done with no dependents: emits review_passed + task_auto_done,
 *      task YAML written with status=done
 *   2. passed — task done with one dependent that becomes ready:
 *      emits auto_ready_cascade, sibling transitions todo → ready
 *   3. passed — task done with a dependent that still has unmet deps:
 *      sibling stays todo, no auto_ready_cascade event
 *   4. passed — all tasks done → emits all_tasks_done
 *   5. passed — writeDoneAndCascade git failure → emits auto_done_failed
 *   6. dispatchReviewResult.change_requested routing still works
 *   7. dispatchReviewResult.escalate routing still works
 *
 * writeDoneAndCascade unit tests (no dispatchReviewResult wrapper):
 *   8. Writes status=done and done log entry
 *   9. Cascade: sibling with satisfied dep transitions to ready
 *   10. Cascade: sibling with unsatisfied dep stays todo
 *   11. allTasksDone=true when all siblings are done
 *   12. allTasksDone=false when a sibling is still in progress
 */

import { describe, it, expect, vi, afterEach, beforeEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import { spawnSync } from "node:child_process";
import type { Task } from "../src/types/task.js";

// ── Mock git operations ───────────────────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "test-feature";
const TASK_ID = "T1";
const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
const GIT_AUTHOR_EMAIL = "bot@test.com";
const GIT_AUTHOR_NAME = "Test Bot";
const PR_URL = "https://github.com/org/repo/pull/42";

function makeTask(id: string, overrides: Partial<Task> = {}): Task {
  return {
    id,
    title: `Task ${id}`,
    repo: "test-repo",
    status: "in_review",
    depends_on: [],
    blocked_reason: null,
    blocked_context: null,
    branch: `feature/${FEATURE_ID}-${id}`,
    execution: {
      actor_type: "agent",
      last_updated_by: null,
      last_updated_at: null,
    },
    pr: { url: PR_URL, status: "open" },
    workspace_pr: null,
    log: [],
    ...overrides,
  };
}

function mockPushSuccess(): ReturnType<typeof spawnSync> {
  return {
    pid: 0, output: [], stdout: "", stderr: "",
    status: 0, signal: null, error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

function mockPushFailure(stderr = "push rejected"): ReturnType<typeof spawnSync> {
  return {
    pid: 0, output: [], stdout: "", stderr,
    status: 1, signal: null, error: undefined,
  } as unknown as ReturnType<typeof spawnSync>;
}

// ── Temp workspace helpers ────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspaceWithTasks(tasks: Task[]): string {
  const dir = mkdtempSync(join(tmpdir(), "dispatch-review-result-"));
  tmpDirs.push(dir);
  const tasksDir = join(dir, "docs", "features", FEATURE_ID, "tasks");
  mkdirSync(tasksDir, { recursive: true });
  for (const task of tasks) {
    writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");
  }
  return dir;
}

function readTaskFromDir(wsRoot: string, taskId: string): Task {
  return parseYaml(
    readFileSync(
      join(wsRoot, "docs", "features", FEATURE_ID, "tasks", `${taskId}.yaml`),
      "utf-8",
    ),
  ) as Task;
}

// ── Setup ─────────────────────────────────────────────────────────────────────

afterEach(() => {
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
  vi.clearAllMocks();
  vi.resetModules();
});

const baseDispatchOpts = {
  workspaceRoot: "/fake",
  featureId: FEATURE_ID,
  taskId: TASK_ID,
  gitAuthorEmail: GIT_AUTHOR_EMAIL,
};

// ── dispatchReviewResult — passed branch ──────────────────────────────────────

describe("dispatchReviewResult — passed: single task with no dependents", () => {
  it("emits review_passed and task_auto_done; writes done status to YAML", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const task = makeTask(TASK_ID, { status: "in_review" });
    const wsRoot = makeWorkspaceWithTasks([task]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "passed", verdict: "approve", confidence: 0.95, notes: "LGTM", review_url: PR_URL },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      gitAuthorName: GIT_AUTHOR_NAME,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "review_passed")).toBe(true);
    expect(events.some((e) => e.type === "task_auto_done")).toBe(true);
    expect(events.some((e) => e.type === "auto_done_failed")).toBe(false);

    const updated = readTaskFromDir(wsRoot, TASK_ID);
    expect(updated.status).toBe("done");
    const doneEntry = updated.log.find((e) => e.action === "done");
    expect(doneEntry).toBeDefined();
    expect(doneEntry?.by).toBe(GIT_AUTHOR_EMAIL);
    expect(doneEntry?.note).toContain(PR_URL);
  });

  it("does not emit auto_ready_cascade when there are no dependents", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const task = makeTask(TASK_ID, { status: "in_review" });
    const wsRoot = makeWorkspaceWithTasks([task]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "passed", verdict: "approve", confidence: 0.9, notes: "", review_url: PR_URL },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "auto_ready_cascade")).toBe(false);
  });
});

describe("dispatchReviewResult — passed: task done with one dependent that becomes ready", () => {
  it("emits auto_ready_cascade and sibling transitions to ready", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const t1 = makeTask(TASK_ID, { status: "in_review" });
    const t2 = makeTask("T2", { status: "todo", depends_on: [TASK_ID] });
    const wsRoot = makeWorkspaceWithTasks([t1, t2]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "passed", verdict: "approve", confidence: 0.9, notes: "", review_url: PR_URL },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    const cascadeEvent = events.find((e) => e.type === "auto_ready_cascade");
    expect(cascadeEvent).toBeDefined();
    expect((cascadeEvent as { readied_task_ids: string[] }).readied_task_ids).toContain("T2");

    const t2Updated = readTaskFromDir(wsRoot, "T2");
    expect(t2Updated.status).toBe("ready");
    const readyEntry = t2Updated.log.find((e) => e.action === "ready");
    expect(readyEntry).toBeDefined();
  });
});

describe("dispatchReviewResult — passed: task done with a dependent that still has unmet deps", () => {
  it("sibling stays todo; no auto_ready_cascade event", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const t1 = makeTask(TASK_ID, { status: "in_review" });
    const t3 = makeTask("T3", { status: "todo" }); // not done
    // T2 depends on both T1 (completing now) and T3 (still todo)
    const t2 = makeTask("T2", { status: "todo", depends_on: [TASK_ID, "T3"] });
    const wsRoot = makeWorkspaceWithTasks([t1, t2, t3]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { dispatchReviewResult } = await import("../src/side-effects/dispatch-review-result.js");
    const events: Record<string, unknown>[] = [];

    await dispatchReviewResult({
      result: { terminal_status: "passed", verdict: "approve", confidence: 0.9, notes: "", review_url: PR_URL },
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
      emit: (e) => events.push(e),
    });

    expect(events.some((e) => e.type === "auto_ready_cascade")).toBe(false);
    expect(readTaskFromDir(wsRoot, "T2").status).toBe("todo");
  });
});

describe("dispatchReviewResult — passed: all tasks done → emits all_tasks_done", () => {
  it("emits all_tasks_done when T1 is the last task", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const t1 = makeTask(TASK_ID, { status: "in_review" });
