describe("writeDoneAndCascade — writes status=done and done log entry", () => {
  it("sets task status to done and appends log entry with PR URL", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const task = makeTask(TASK_ID, { status: "in_review" });
    const wsRoot = makeWorkspaceWithTasks([task]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { writeDoneAndCascade } = await import("../src/side-effects/write-done-and-cascade.js");
    const result = writeDoneAndCascade({
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      prUrl: PR_URL,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
    });

    expect(result.error).toBeUndefined();

    const updated = readTaskFromDir(wsRoot, TASK_ID);
    expect(updated.status).toBe("done");
    expect(updated.execution.last_updated_by).toBe(GIT_AUTHOR_EMAIL);

    const doneEntry = updated.log.find((e) => e.action === "done");
    expect(doneEntry).toBeDefined();
    expect(doneEntry?.by).toBe(GIT_AUTHOR_EMAIL);
    expect(doneEntry?.at).toBeDefined();
    expect(doneEntry?.note).toContain(PR_URL);
  });

  it("appends done log entry without PR URL when prUrl is omitted", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const task = makeTask(TASK_ID, { status: "in_review" });
    const wsRoot = makeWorkspaceWithTasks([task]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { writeDoneAndCascade } = await import("../src/side-effects/write-done-and-cascade.js");
    const result = writeDoneAndCascade({
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
    });

    expect(result.error).toBeUndefined();
    const updated = readTaskFromDir(wsRoot, TASK_ID);
    const doneEntry = updated.log.find((e) => e.action === "done");
    expect(doneEntry?.note).toContain("Reviewer approved");
  });
});

describe("writeDoneAndCascade — cascade: sibling with satisfied dep transitions to ready", () => {
  it("returns readiedTaskIds containing the unblocked sibling", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const t1 = makeTask(TASK_ID, { status: "in_review" });
    const t2 = makeTask("T2", { status: "todo", depends_on: [TASK_ID] });
    const wsRoot = makeWorkspaceWithTasks([t1, t2]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { writeDoneAndCascade } = await import("../src/side-effects/write-done-and-cascade.js");
    const result = writeDoneAndCascade({
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      prUrl: PR_URL,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
    });

    expect(result.error).toBeUndefined();
    expect(result.readiedTaskIds).toContain("T2");

    const t2Updated = readTaskFromDir(wsRoot, "T2");
    expect(t2Updated.status).toBe("ready");
    const readyEntry = t2Updated.log.find((e) => e.action === "ready");
