describe("writeDoneAndCascade — allTasksDone", () => {
  it("returns allTasksDone=true when the completed task is the only task", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const t1 = makeTask(TASK_ID, { status: "in_review" });
    const wsRoot = makeWorkspaceWithTasks([t1]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { writeDoneAndCascade } = await import("../src/side-effects/write-done-and-cascade.js");
    const result = writeDoneAndCascade({
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
    });

    expect(result.allTasksDone).toBe(true);
  });

  it("returns allTasksDone=false when a sibling is still in_progress", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const t1 = makeTask(TASK_ID, { status: "in_review" });
    const t2 = makeTask("T2", { status: "in_progress" }); // not done
    const wsRoot = makeWorkspaceWithTasks([t1, t2]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { writeDoneAndCascade } = await import("../src/side-effects/write-done-and-cascade.js");
    const result = writeDoneAndCascade({
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
    });

    expect(result.allTasksDone).toBe(false);
  });

  it("returns allTasksDone=true when all siblings are done or cancelled", async () => {
    const { execSync } = await import("node:child_process");
    const { spawnSync: spMock } = await import("node:child_process");

    const t1 = makeTask(TASK_ID, { status: "in_review" });
    const t2 = makeTask("T2", { status: "done" });
    const t3 = makeTask("T3", { status: "cancelled" }); // cancelled counts as terminal
    const wsRoot = makeWorkspaceWithTasks([t1, t2, t3]);

    vi.mocked(execSync).mockImplementation(() => Buffer.from(""));
    vi.mocked(spMock).mockReturnValue(mockPushSuccess());

    const { writeDoneAndCascade } = await import("../src/side-effects/write-done-and-cascade.js");
    const result = writeDoneAndCascade({
      workspaceRoot: wsRoot,
      featureId: FEATURE_ID,
      taskId: TASK_ID,
      taskBranch: TASK_BRANCH,
      gitAuthorEmail: GIT_AUTHOR_EMAIL,
    });

    expect(result.allTasksDone).toBe(true);
  });
});

